begin;
do $test$
declare
 owner_id uuid:=gen_random_uuid(); other_id uuid:=gen_random_uuid(); admin_id uuid:=gen_random_uuid();
 event_key text:='fields-test-'||gen_random_uuid(); item_id uuid:=gen_random_uuid(); legacy_id text:='fixture-'||gen_random_uuid();
 original jsonb; saved jsonb; blocked boolean;
begin
 insert into auth.users(id,aud,role,is_anonymous) values(owner_id,'authenticated','authenticated',true),(other_id,'authenticated','authenticated',true);
 insert into auth.users(id,aud,role,is_anonymous,email,email_confirmed_at) values(admin_id,'authenticated','authenticated',false,admin_id::text||'@example.invalid',now());
 insert into public.group_members(user_id,display_name) values(owner_id,'FieldsOwner-'||owner_id),(other_id,'FieldsOther-'||other_id),(admin_id,'FieldsAdmin-'||admin_id);
 insert into group_private.admins(member_key) values(admin_id::text);
 insert into public.group_events(id,title,created_by_key,start_date,end_date) values(event_key,'Activity fields test',owner_id::text,'2027-09-02','2027-09-05');
 insert into public.group_program_items(id,event_id,title,created_by_key) values(item_id,event_key,'Original',owner_id::text);
 insert into public.trip_activity_details(activity_id,title) values(legacy_id,'Fixture original');
 insert into public.trip_text_content(site_id,content_key,content) values('kufstein-2026','activity-'||legacy_id||'-description',null);
 -- Exercise member INSERT/UPDATE triggers through the actual browser role too.
 insert into public.group_events(id,title,created_by_key) values(event_key||'-planning','Planning fixture',owner_id::text);
 insert into public.group_event_dates(event_id,start_date,end_date) values(event_key||'-planning','2027-09-02','2027-09-05');
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('role','authenticated',true);
 insert into public.group_program_items(event_id,title,created_by_key,day_number,start_time,end_time) values(event_key||'-planning','Member-added idea',owner_id::text,4,'09:00','10:00');
 blocked:=false;begin update public.group_program_items set day_number=5 where event_id=event_key||'-planning';exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Direct member write accepted invalid proposed trip day';end if;
 perform set_config('role','postgres',true);
 select to_jsonb(i) into original from public.group_program_items i where id=item_id;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('role','authenticated',true);
 saved:=public.save_event_content_fields('program',item_id::text,'{"title":"Changed","website_url":"https://example.invalid/","description":"Test description","day_number":1,"start_time":"23:00","end_time":"01:00","ends_next_day":true,"image_url":"https://example.invalid/photo.jpg","image_source_url":"https://example.invalid/","image_credit":"Fixture"}',original);
 if saved->>'title'<>'Changed' or saved->>'day_number'<>'1' then raise exception 'Owner atomic save failed';end if;
 blocked:=false;begin perform public.save_event_content_fields('program',item_id::text,'{"title":"Stale"}',original);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Stale overwrite accepted';end if;
 blocked:=false;begin perform public.save_event_content_fields('program',item_id::text,'{"day_number":5}',saved);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Out-of-range trip day accepted';end if;
 blocked:=false;begin perform public.save_event_content_fields('program',item_id::text,'{"day_number":4}',saved);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Overnight final day accepted';end if;
 blocked:=false;begin perform public.save_event_content_fields('program',item_id::text,'{"website_url":"https://user:password@example.invalid"}',saved);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Unsafe URL accepted';end if;
 blocked:=false;begin perform public.save_event_content_fields('program',item_id::text,'{"created_by_key":"bad"}',saved);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Ownership change accepted';end if;
 perform set_config('request.jwt.claim.sub',other_id::text,true);
 blocked:=false;begin perform public.save_event_content_fields('program',item_id::text,'{"title":"Other"}',saved);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Other member changed activity';end if;
 blocked:=false;begin perform public.save_kufstein_activity(legacy_id,'{"title":"Other"}',0);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Member changed legacy activity';end if;
 perform set_config('request.jwt.claim.sub',admin_id::text,true);
 saved:=public.save_event_content_fields('program',item_id::text,'{"title":"Admin changed"}',saved);
 if saved->>'title'<>'Admin changed' then raise exception 'Admin save failed';end if;
 saved:=public.save_kufstein_activity(legacy_id,'{"title":"Changed fixture","description":"Description","website_url":"https://example.invalid/","day_number":1,"start_time":"09:00","end_time":"10:00","ends_next_day":false}',0);
 if saved->>'title'<>'Changed fixture' or saved->>'revision'<>'1' then raise exception 'Legacy save failed';end if;
 if not exists(select 1 from public.trip_text_content where content_key='activity-'||legacy_id||'-description' and content='Description') then raise exception 'Legacy content not mirrored';end if;
 blocked:=false;begin perform public.save_kufstein_activity(legacy_id,'{"title":"Stale"}',0);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Legacy stale overwrite accepted';end if;
 blocked:=false;begin perform public.save_kufstein_activity(legacy_id,'{"day_number":3}',1);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Legacy out-of-range date accepted';end if;
 blocked:=false;begin perform public.save_kufstein_activity(legacy_id,'{"day_number":2,"ends_next_day":true}',1);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Legacy overnight beyond trip accepted';end if;
 blocked:=false;begin perform public.save_kufstein_activity(legacy_id,'{"website_url":"javascript:alert(1)"}',1);exception when check_violation then blocked:=true;end;
 if not blocked then raise exception 'Legacy unsafe URL accepted';end if;
 blocked:=false;begin perform public.save_trip_text('kufstein-2026','activity-'||legacy_id||'-description','Old editor',1);exception when raise_exception then blocked:=true;end;
 if not blocked then raise exception 'Old editor can overwrite structured fields';end if;
 blocked:=false;begin update public.trip_activity_details set title='Direct overwrite' where activity_id=legacy_id;exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Legacy direct UPDATE granted';end if;
 perform set_config('request.jwt.claim.sub','',true);perform set_config('role','anon',true);
 blocked:=false;begin perform public.save_kufstein_activity(legacy_id,'{"title":"Anon"}',1);exception when insufficient_privilege then blocked:=true;end;
 if not blocked then raise exception 'Anon legacy save granted';end if;
 perform set_config('role','postgres',true);
end $test$;
select 'PASS: atomic title/link/description/schedule/photo save; creator/admin permissions; stale conflicts; safe URLs; trip boundaries; legacy revisions and readonly table; old editor blocked' as verification;
rollback;
